--
-- Table structure for table `cities`
--

DROP TABLE IF EXISTS `cities`;
CREATE TABLE IF NOT EXISTS `cities` (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `state_id` bigint UNSIGNED NOT NULL,
  `country_id` bigint UNSIGNED NOT NULL,
  `postal_code_pattern` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_major` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `cities_state_id_is_active_index` (`state_id`,`is_active`),
  KEY `cities_country_id_is_major_index` (`country_id`,`is_major`)
) ENGINE=MyISAM AUTO_INCREMENT=4200 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

